package com.oneilsoftware.sbp.framework.storage;

import java.util.Optional;

/**
 * Provider-neutral document/object storage contract (framework FR-11, ADR-DOC-002). Business
 * modules store and retrieve file content only through this contract, never through a concrete
 * storage vendor, so a customer deployment can select its own approved implementation (database,
 * object store, filesystem) without changing module code.
 *
 * <p>Keys are opaque strings generated by the consuming module (for Document, the Document UUID).
 * Content is treated as a bounded byte payload: the Document module rejects files over its
 * configured size limit before they reach storage.
 *
 * <p>The contract is synchronous and does not promise atomicity across stores. The reference
 * database-backed implementation participates in the calling module's transaction; a remote-store
 * implementation supplies its own failure semantics under its deployment's policy.
 */
public interface BlobStorage {

	/**
	 * Stores {@code content} under {@code key}, replacing any existing content for that key.
	 */
	void store(String key, byte[] content, String contentType);

	/**
	 * Returns the content stored under {@code key}, or empty when no content exists for that key.
	 */
	Optional<byte[]> load(String key);

	/**
	 * Removes the content stored under {@code key}. Deleting a key with no stored content is a
	 * no-op.
	 */
	void delete(String key);
}
